def _ppt_bytes() -> bytes:
    """Минимальный двоичный ``.ppt`` (OLE2/CFBF) — только stdlib.

    Один поток ``PowerPoint Document`` с контейнером Document и парой текстовых
    атомов (``TextCharsAtom`` — UTF-16LE, ``TextBytesAtom`` — ANSI). Поток добит
    филлер-записью до 4096 байт, чтобы не заводить mini-stream в CFBF. Все метки
    времени нулевые — генерация детерминирована.
    """
    free, endofchain, fatsect, nostream = 0xFFFFFFFF, 0xFFFFFFFE, 0xFFFFFFFD, 0xFFFFFFFF
    sector = 512

    def rec(ver_inst: int, rtype: int, body: bytes) -> bytes:
        return struct.pack("<HHI", ver_inst, rtype, len(body)) + body

    atoms = (
        rec(0x0000, 0x0FA0, "Слайд 1: заголовок презентации".encode("utf-16-le"))
        + rec(0x0000, 0x0FA8, b"Slide 2 body text (ANSI atom)")
        + rec(0x0000, 0x0FA0, "Слайд 3: заключение".encode("utf-16-le"))
    )
    stream = rec(0x000F, 0x03E8, atoms)  # Document container (recVer=0xF)
    if len(stream) + 8 < 4096:
        stream += rec(0x0000, 0x0FFF, b"\x00" * (4096 - len(stream) - 8))

    n_sec = (len(stream) + sector - 1) // sector
    stream_padded = stream + b"\x00" * (n_sec * sector - len(stream))
    stream_start = 2

    fat = [free] * (sector // 4)
    fat[0] = fatsect
    fat[1] = endofchain
    for k in range(n_sec):
        fat[stream_start + k] = endofchain if k == n_sec - 1 else stream_start + k + 1
    fat_bytes = struct.pack(f"<{len(fat)}I", *fat)

    def dir_entry(name: str, obj_type: int, start: int, size: int, child: int = nostream) -> bytes:
        raw = name.encode("utf-16-le")[:62]
        return struct.pack(
            "<64sHBBIII16sIQQIQ",
            raw + b"\x00" * (64 - len(raw)),
            len(raw) + 2,
            obj_type,
            0x01,
            nostream,
            nostream,
            child,
            b"\x00" * 16,
            0,
            0,
            0,
            start,
            size,
        )

    directory = (
        dir_entry("Root Entry", 0x05, endofchain, 0, child=1)
        + dir_entry("PowerPoint Document", 0x02, stream_start, len(stream))
        + dir_entry("", 0x00, 0, 0) * 2
    )
    directory += b"\x00" * (sector - len(directory))

    header = bytearray(sector)
    header[0:8] = b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"
    struct.pack_into("<H", header, 24, 0x003E)
    struct.pack_into("<H", header, 26, 0x0003)
    struct.pack_into("<H", header, 28, 0xFFFE)
    struct.pack_into("<H", header, 30, 0x0009)
    struct.pack_into("<H", header, 32, 0x0006)
    struct.pack_into("<I", header, 44, 1)          # число FAT-секторов
    struct.pack_into("<I", header, 48, 1)          # первый сектор каталога
    struct.pack_into("<I", header, 56, 4096)       # порог mini-stream
    struct.pack_into("<I", header, 60, endofchain) # первый mini-FAT сектор
    struct.pack_into("<I", header, 68, endofchain) # первый DIFAT сектор
    difat = [free] * 109
    difat[0] = 0
    struct.pack_into("<109I", header, 76, *difat)

    return bytes(header) + fat_bytes + directory + stream_padded

