def _write_minimal_doc() -> bytes:
    """Минимальный OLE2 Compound File с потоком WordDocument (legacy .doc)."""
    magic = b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"
    base_text = (
        "Заголовок DOC-документа\r\n"
        "Это демонстрационный legacy DOC-документ для pyqt-omniviewer.\r\n"
        "Первый пункт\r\nВторой пункт\r\nТретий пункт\r\n"
    )
    while len(base_text.encode("utf-8")) < 4100:
        base_text += "Дополнительный абзац текста для заполнения.\r\n"
    text_bytes = base_text.encode("utf-8")
    num_data_sectors = (len(text_bytes) + 511) // 512

    header_data = struct.pack(
        "<8s16sHHHHHHLLLLLLLLLL",
        magic,
        b"\x00" * 16,
        0x003E,
        0x0003,
        0xFFFE,
        0x0009,
        0x0006,
        0,
        0,
        0,
        1,
        0,
        0,
        0x00001000,
        0xFFFFFFFE,
        0,
        0xFFFFFFFE,
        0,
    )
    difat = struct.pack("<I", 1) + b"".join(struct.pack("<I", 0xFFFFFFFF) for _ in range(108))
    header = header_data + difat

    fat = bytearray(512)
    struct.pack_into("<I", fat, 0, 0xFFFFFFFE)
    struct.pack_into("<I", fat, 4, 0xFFFFFFFD)
    for i in range(num_data_sectors):
        sect_id = 2 + i
        struct.pack_into(
            "<I", fat, sect_id * 4, sect_id + 1 if i < num_data_sectors - 1 else 0xFFFFFFFE
        )
    for i in range(2 + num_data_sectors, 128):
        struct.pack_into("<I", fat, i * 4, 0xFFFFFFFF)

    dir_sect = bytearray(512)
    rn = "Root Entry".encode("utf-16-le") + b"\x00\x00"
    dir_sect[0 : len(rn)] = rn
    struct.pack_into("<H", dir_sect, 0x40, len(rn))
    dir_sect[0x42] = 5
    dir_sect[0x43] = 1
    struct.pack_into("<I", dir_sect, 0x44, 0xFFFFFFFF)
    struct.pack_into("<I", dir_sect, 0x48, 0xFFFFFFFF)
    struct.pack_into("<I", dir_sect, 0x4C, 1)
    struct.pack_into("<I", dir_sect, 0x74, 0xFFFFFFFE)
    struct.pack_into("<I", dir_sect, 0x78, 0)

    e1 = 128
    sn = "WordDocument".encode("utf-16-le") + b"\x00\x00"
    dir_sect[e1 : e1 + len(sn)] = sn
    struct.pack_into("<H", dir_sect, e1 + 0x40, len(sn))
    dir_sect[e1 + 0x42] = 2
    dir_sect[e1 + 0x43] = 1
    struct.pack_into("<I", dir_sect, e1 + 0x44, 0xFFFFFFFF)
    struct.pack_into("<I", dir_sect, e1 + 0x48, 0xFFFFFFFF)
    struct.pack_into("<I", dir_sect, e1 + 0x4C, 0xFFFFFFFF)
    struct.pack_into("<I", dir_sect, e1 + 0x74, 2)
    struct.pack_into("<I", dir_sect, e1 + 0x78, len(text_bytes))

    for idx in range(2, 4):
        off = idx * 128
        dir_sect[off + 0x42] = 0
        struct.pack_into("<I", dir_sect, off + 0x44, 0xFFFFFFFF)
        struct.pack_into("<I", dir_sect, off + 0x48, 0xFFFFFFFF)
        struct.pack_into("<I", dir_sect, off + 0x4C, 0xFFFFFFFF)

    data_sectors = bytearray(num_data_sectors * 512)
    data_sectors[: len(text_bytes)] = text_bytes

    return bytes(header) + bytes(dir_sect) + bytes(fat) + bytes(data_sectors)


def _ipynb_bytes() -> bytes:
    """Jupyter-ноутбук (nbformat 4.5) — обычный JSON, собирается stdlib.

    Ячейка Markdown, ячейка кода с текстовым выводом (stream + execute_result) и
    ячейка кода с выводом-картинкой (`image/png`, тот же swatch, base64). Все
    `id` фиксированы — генерация детерминирована.
    """
    import json

    png_b64 = base64.b64encode(_swatch_png()).decode("ascii")
    nb = {
        "nbformat": 4,
        "nbformat_minor": 5,
        "metadata": {
            "kernelspec": {"name": "python3", "language": "python", "display_name": "Python 3"},
            "language_info": {"name": "python", "version": "3.12"},
        },
        "cells": [
            {
                "cell_type": "markdown",
                "id": "cell-md-1",
                "metadata": {},
                "source": [
                    "# Демонстрационный ноутбук\n",
                    "\n",
                    "Ячейка **Markdown**: заголовок, список, `инлайн-код`.\n",
                    "\n",
                    "- считаем площадь круга\n",
                    "- выводим текст и картинку\n",
                ],
            },
            {
                "cell_type": "code",
                "id": "cell-code-1",
                "metadata": {},
                "execution_count": 1,
                "source": [
                    "import math\n",
                    "\n",
                    "\n",
                    "def area(r):\n",
                    "    return math.pi * r * r\n",
                    "\n",
                    "\n",
                    "print(round(area(2), 3))\n",
                    "area(2)\n",
                ],
                "outputs": [
                    {"output_type": "stream", "name": "stdout", "text": ["12.566\n"]},
                    {
                        "output_type": "execute_result",
                        "execution_count": 1,
                        "metadata": {},
                        "data": {"text/plain": ["12.566370614359172"]},
                    },
                ],
            },
            {
                "cell_type": "code",
                "id": "cell-code-2",
                "metadata": {},
                "execution_count": 2,
                "source": ["# вывод-картинка (PNG, вложён в ноутбук)\n", "render_swatch()\n"],
                "outputs": [
                    {
                        "output_type": "display_data",
                        "metadata": {},
                        "data": {
                            "image/png": png_b64,
                            "text/plain": ["<Figure size 32x32>"],
                        },
                    }
                ],
            },
        ],
    }
    return (json.dumps(nb, ensure_ascii=False, indent=1) + "\n").encode("utf-8")


def build(dest: Path) -> list[Path]:
    """Наполнить ``dest`` всеми скриптуемыми образцами. Идемпотентно.

    Возвращает отсортированный список записанных путей.
    """
    dest = Path(dest)
    png = _swatch_png()
    jpeg = _JPEG_16
    record_json = _RECORD_JSON
    catalog_xml = _CATALOG_XML
    pdf = _write_minimal_pdf()
    mp4 = _MP4
    sample_zip = _zip_bytes()

    written = [
        _write(dest / "text/plain-en.txt", _PLAIN_EN),
        _write(dest / "text/notes-ru.txt", _NOTES_RU),
        _write(dest / "code/example.py", _EXAMPLE_PY),
        _write(dest / "code/example.c", _EXAMPLE_C),
        _write(dest / "data/table.csv", _csv_bytes(",")),
        _write(dest / "data/table.tsv", _csv_bytes("\t")),
        _write(dest / "data/table.xlsx", _XLSX),
        _write(dest / "data/table.ods", _ODS),
        _write(dest / "data/table.xls", _XLS),

        _write(dest / "data/record.json", record_json),
        _write(dest / "data/config.yaml", _CONFIG_YAML),
        _write(dest / "data/config.toml", _CONFIG_TOML),
        _write(dest / "data/catalog.xml", catalog_xml),
        _write(dest / "data/settings.ini", _SETTINGS_INI),
        # Крупный структурированный файл — проверка ленивого дерева структуры.
        _write(dest / "data/big-tree.json", _big_tree_json()),
        # Экзотика для fallback: MIDI разбирается hachoir, opaque.bin — нет.
        _write(dest / "misc/exotic.mid", _midi_bytes()),
        _write(dest / "misc/opaque.bin", _OPAQUE_BIN),
        _write(dest / "images/swatch.png", png),
        _write(dest / "images/swatch.jpg", jpeg),
        _write(dest / "images/sample.heic", _HEIC_SAMPLE),
        _write(dest / "images/sample.avif", _AVIF_SAMPLE),
        _write(dest / "images/multipage.tiff", _TIFF_MULTIPAGE),
        _write(dest / "images/sample.dng", _DNG_SAMPLE),
        _write(dest / "books/sample.pdf", pdf),
        _write(dest / "books/sample.cbz", _write_minimal_cbz()),
        _write(dest / "books/sample.epub", _write_minimal_epub()),
        _write(dest / "books/sample.fb2", _write_minimal_fb2()),
        _write(dest / "books/sample.xps", _write_minimal_xps()),
        _write(dest / "large/big-lines.txt", _big_text_bytes()),
        _write(dest / "noext/hello-script", _SHEBANG_SCRIPT),
        # Видео: по одному короткому образцу на контейнер, который умеет MediaViewer.
        _write(dest / "media/sample.mp4", mp4),
        _write(dest / "media/sample.mkv", _MKV),
        _write(dest / "media/sample.avi", _AVI),
        _write(dest / "media/sample.webm", _WEBM),
        _write(dest / "media/sample.mov", _MOV),
        # Аудио: контейнеры с тегами и (где есть) обложкой.
        _write(dest / "media/sample.mp3", _MP3),
        _write(dest / "media/sample.flac", _FLAC),
        _write(dest / "media/sample.wav", _WAV),
        _write(dest / "media/sample.ogg", _OGG),
        _write(dest / "media/sample.m4a", _M4A),
        _write(dest / "media/sample.opus", _OPUS),
        # Архивы (только stdlib: zipfile / tarfile / ручной ar).
        _write(dest / "archives/sample.zip", sample_zip),
        _write(dest / "archives/sample.tar.gz", _tar_gz_bytes()),
        _write(dest / "archives/sample.ar", _ar_bytes()),
        _write(dest / "archives/nested.zip", _nested_zip_bytes()),
        # Разметка: Markdown / HTML / XHTML / MHTML (общий шов «→ HTML → QTextBrowser»).
        _write(dest / "markup/sample.md", _MARKDOWN_SAMPLE),
        _write(dest / "markup/page.html", _HTML_SAMPLE),
        _write(dest / "markup/page.xhtml", _XHTML_SAMPLE),
        _write(dest / "markup/saved.mhtml", _mhtml_bytes()),
        # Презентации: PPTX / ODP (base64-блобы) и собранный вручную legacy .ppt.
        _write(dest / "presentations/sample.pptx", _PPTX_SAMPLE),
        _write(dest / "presentations/sample.odp", _ODP_SAMPLE),
        _write(dest / "presentations/sample.ppt", _ppt_bytes()),
        # Офисные документы: DOCX, legacy DOC, ODT, RTF
        _write(dest / "documents/sample.docx", _write_minimal_docx()),
        _write(dest / "documents/sample.doc", _write_minimal_doc()),
        _write(dest / "documents/sample.odt", _ODT_SAMPLE),
        _write(dest / "documents/sample.rtf", _RTF_SAMPLE),
        # Jupyter-ноутбук: обычный JSON, рендерится nbconvert (шаблон basic).
        _write(dest / "notebooks/sample.ipynb", _ipynb_bytes()),
        # Шрифты: TTF/OTF собраны fontTools, WOFF/WOFF2 — те же данные в web-обёртке.
        _write(dest / "fonts/sample.ttf", _TTF_SAMPLE),
        _write(dest / "fonts/sample.otf", _OTF_SAMPLE),
        _write(dest / "fonts/sample.woff", _WOFF_SAMPLE),
        _write(dest / "fonts/sample.woff2", _WOFF2_SAMPLE),
        # Почта: EML собран из строки с фиксированными границами, MSG —
        # минимальный CFBF/OLE2 (собран вручную скриптом), вложён как base64.
        _write(dest / "mail/sample.eml", _eml_bytes()),
        _write(dest / "mail/sample.msg", _MSG_SAMPLE),
        # «Битые» образцы: обрезки валидных файлов — просмотрщик обязан отдать
        # аккуратный «ошибочный» виджет, а не упасть.
        _write(dest / "broken/truncated.png", png[: len(png) // 2]),
        _write(dest / "broken/truncated.jpg", jpeg[: len(jpeg) // 3]),
        _write(dest / "broken/truncated.json", record_json[:60]),
        _write(dest / "broken/truncated.xml", catalog_xml[:80]),
        _write(dest / "broken/truncated.toml", b'name = "demo\nversion = [1, 2'),
        _write(dest / "broken/truncated.pdf", pdf[: 10]),
        _write(dest / "broken/truncated.mp4", mp4[:10]),
        _write(dest / "broken/truncated.mp3", _MP3[:10]),
        _write(dest / "broken/truncated.xlsx", _XLSX[:10]),
        _write(dest / "broken/truncated.heic", _HEIC_SAMPLE[: len(_HEIC_SAMPLE) // 3]),
        _write(dest / "broken/truncated.zip", sample_zip[:24]),
        _write(dest / "broken/truncated.mhtml", _mhtml_bytes()[:90]),
        _write(dest / "broken/truncated.pptx", _PPTX_SAMPLE[: len(_PPTX_SAMPLE) // 3]),
        _write(dest / "broken/truncated.docx", _write_minimal_docx()[:50]),
        _write(dest / "broken/truncated.doc", _write_minimal_doc()[:50]),
        _write(dest / "broken/truncated.odt", _ODT_SAMPLE[:50]),
        _write(dest / "broken/truncated.rtf", _RTF_SAMPLE[:17]),
        _write(dest / "broken/truncated.ipynb", _ipynb_bytes()[: len(_ipynb_bytes()) // 3]),
        _write(dest / "broken/truncated.ttf", _TTF_SAMPLE[: len(_TTF_SAMPLE) // 3]),
        _write(dest / "broken/truncated.msg", _MSG_SAMPLE[: len(_MSG_SAMPLE) // 3]),
    ]
    return sorted(written)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Сгенерировать демонстрационные образцы demo/.")
    parser.add_argument(
        "--dest",
        type=Path,
        default=DEMO_DIR,
        help="каталог назначения (по умолчанию — каталог самого скрипта)",
    )
    args = parser.parse_args(argv)

    written = build(args.dest)
    total = sum(p.stat().st_size for p in written)
    print(f"demo/generate: {len(written)} файлов, {total / 1024:.1f} КБ -> {args.dest}")
    if total >= SIZE_BUDGET_BYTES:
        print("ВНИМАНИЕ: превышен бюджет размера demo/ (< 5 МБ)", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
